export const answerLedger=(s,key,field,value,o={})=>id(field)&&str(value,40)&&editAnswer(s,key,(a,t)=>{if(t.kind!=='numeric'||!known(t.fields,field))return false;a.fields[field]=value;return true;},o);
export const noneLedger=(s,key,field,value,o={})=>id(field)&&typeof value==='boolean'&&editAnswer(s,key,(a,t)=>{if(t.kind!=='numeric'||!known(t.fields,field))return false;a.none=value?[...new Set([...a.none,field])]:a.none.filter(k=>k!==field);return true;},o);
export const choiceLedger=(s,key,value,o={})=>str(value,100)&&editAnswer(s,key,(a,t)=>{if(t.kind!=='choice'||value!==''&&!known(t.choices,value))return false;a.choiceId=value;return true;},o);
export function checkLedger(s,key,o={}){const w=ledgerView(s).work;if(!w||!id(key))return false;const t=taskOf(w.source,key),a=get(w.answers,key);if(!t)return false;if(!validLedgerAnswer(a,t))return {recorded:false,feedback:t.kind==='numeric'?w.source.labels.invalid:'Choose one supplied sentence before checking. This has not added a checked response.'};let match,feedback;
 if(t.kind==='numeric'){if(t.fields.some(f=>!a.none.includes(f.id)&&(!own(a.fields,f.id)||parseRiverNumber(a.fields[f.id])===null)))return {recorded:false,feedback:w.source.labels.invalid};match=t.fields.every(f=>a.none.includes(f.id)?f.answer===null:f.answer!==null&&equalRiverNumber(parseRiverNumber(a.fields[f.id]),f.answer));const error=t.errors.find(e=>!a.none.includes(e.fieldId)&&equalRiverNumber(parseRiverNumber(get(a.fields,e.fieldId)),e.value));feedback=match?t.match:error?.reply||t.different;}
 else{const choice=find(t.choices,a.choiceId);if(!choice)return {recorded:false,feedback:'Choose one supplied sentence before checking. This has not added a checked response.'};match=choice.id===t.fit;feedback=choice.reply;}
 return workChange(s,v=>{if(v.checks.length>=32)return false;const source=projection(v,{task:taskOf(v.source,key)}),c={source,taskId:key,kind:t.kind,raw:clone(a),outcome:match?'match':'different',feedback,shownBefore:Object.keys(source.shown),helpBefore:Object.keys(source.help),priorSupport:priorSupport(v),supported:true};if(!validLedgerCheck(c))return false;v.checks.push(clone(c));if(!own(v.firstChecks,key))v.firstChecks[key]=clone(c);return {...clone(c),recorded:true};},o);}
export const skipLedger=(s,key,o={})=>id(key)&&workChange(s,w=>{const t=taskOf(w.source,key);if(!t)return false;if(!w.help.includes(t.skipId))w.help.push(t.skipId);const tasks=w.source.tasks.filter(x=>x.pageId===t.pageId),i=tasks.findIndex(x=>x.id===key);w.tasks[t.pageId]=tasks[(i+1)%tasks.length].id;return true;},o);
export const claimLedger=(s,key,o={})=>id(key)&&workChange(s,w=>{if(!known(w.source.claims,key))return false;w.claimId=key;reveal(w);return true;},o);
export const assignLedger=(s,key,tray,o={})=>id(key)&&id(tray)&&workChange(s,w=>{const card=find(w.source.claims,key);if(!card||!known(w.source.trays,tray)||w.claimHistory.length>=48||own(w.claims,key)&&!known(w.source.trays,w.claims[key]))return false;const prior=priorSupport(w),code=`claim-${key}-${tray}`;if(own(w.source.help,code)&&!w.help.includes(code))w.help.push(code);const source=projection(w,{card}),c={source,cardId:key,trayId:tray,reply:card.replies[tray],shownBefore:Object.keys(source.shown),helpBefore:Object.keys(source.help),priorSupport:prior};if(!validLedgerClaim(c))return false;w.claims[key]=tray;w.claimHistory.push(clone(c));return true;},o);
export const partLedger=(s,key,o={})=>id(key)&&workChange(s,w=>{if(!known(w.source.parts,key))return false;w.partId=key;reveal(w);return true;},o);
function editPart(s,key,fn,o){return id(key)&&workChange(s,w=>{const source=find(w.source.parts,key);if(!source||own(w.writing,key)&&(!validLedgerPart(w.writing[key])||w.writing[key].choiceId!==''&&!known(source.options,w.writing[key].choiceId)))return false;if(!own(w.writing,key))w.writing[key]={mode:'own',own:'',choiceId:''};return fn(w.writing[key],source)&&validLedgerPart(w.writing[key]);},o);}
export const writingLedger=(s,key,field,value,o={})=>['mode','own','choiceId'].includes(field)&&editPart(s,key,(p,source)=>{if(field==='mode'&&!['own','supplied'].includes(value)||field==='own'&&!str(value,1600)||field==='choiceId'&&value!==''&&!known(source.options,value))return false;p[field]=value;if(field==='choiceId'&&value!=='')p.mode='supplied';return true;},o);
export const starterLedger=(s,key,confirmed=false,o={})=>editPart(s,key,(p,source)=>{const option=find(source.options,p.choiceId);if(!option||p.own!==''&&confirmed!==true)return false;p.own=option.text;p.mode='own';p.starterUsed=true;return true;},o);
export const planLedger=(s,key,o={})=>str(key,100)&&workChange(s,w=>{if(key!==''&&!known(w.source.plans,key))return false;w.planId=key;return true;},o);
const compact=c=>validLedgerCheck(c)?{kind:c.kind,outcome:c.outcome,feedback:c.feedback,raw:clone(c.raw),context:{prompt:c.source.task.prompt,context:c.source.task.context,facts:clone(c.source.task.facts)}}:null;
export const keepLedgerNote=(s,o={})=>workChange(s,w=>{const renderedParts=w.source.parts.map(source=>{const p=get(w.writing,source.id),healthy=validLedgerPart(p)&&(p.choiceId===''||known(source.options,p.choiceId)),option=healthy?find(source.options,p.choiceId):null;return {id:source.id,title:source.title,mode:healthy?p.mode:'own',text:healthy?(p.mode==='own'?p.own:option?.text||''):'',choiceId:healthy?p.choiceId:'',planId:option?.planId||'',...(!healthy&&own(w.writing,source.id)?{unreadable:true}:{}),...(healthy&&own(p,'starterUsed')?{starterUsed:p.starterUsed}:{})};}),responses=[...new Set([...w.checks.filter(c=>obj(c)&&id(c.taskId)).map(c=>c.taskId),...Object.keys(w.firstChecks)])].map(taskId=>{const latest=w.checks.filter(c=>obj(c)&&own(c,'taskId')&&c.taskId===taskId).at(-1);return {taskId,first:compact(get(w.firstChecks,taskId)),latest:compact(latest),latestUnreadable:latest!==undefined&&!validLedgerCheck(latest)};}),claims=w.source.claims.flatMap(card=>{const latest=w.claimHistory.filter(c=>obj(c)&&own(c,'cardId')&&c.cardId===card.id).at(-1);return validLedgerClaim(latest)?[{cardId:latest.cardId,trayId:latest.trayId,reply:latest.reply}]:[];});const k={source:projection(w,{note:true}),planId:w.planId,writing:clone(w.writing),renderedParts,responses,claims,shownBefore:clone(w.shown),helpBefore:clone(w.help),closing:w.source.closing};if(!validLedgerKeep(k))return false;if(!own(w,'firstKept'))w.firstKept=clone(k);w.kept=clone(k);return true;},o);
function activeHelp(w){const p=pageOf(w.source,w.pageId),t=taskOf(w.source,get(w.tasks,p.id)),card=find(w.source.claims,w.claimId),part=find(w.source.parts,w.partId);return new Set([`audio-${p.id}`,`together-${p.id}`,...w.source.sources.map(c=>`source-${c.id}`),...(t?[t.hintId,t.exampleId,t.skipId]:[]),...(p.role==='claims'&&card?[card.hintId,card.exampleId,'claim-skip']:[]),...(p.role==='note'&&part?[part.helpId]:[])]);}
export function ledgerFacts(s){try{const w=ledgerView(s).work;if(!w)return [];const found=new Map(),add=ps=>{if(pairs(ps))for(const [a,b]of ps)for(const p of [[a,b],[b,a]])found.set(p.join(','),p);};const p=pageOf(w.source,w.pageId),state=get(w.learn,p.id);if(validLedgerLearn(state,p)&&!state.folded){for(const l of p.learn.slice(0,state.count))add(l.facts);const target=p.guidedFor,visible=!target||target.kind==='task'&&get(w.tasks,p.id)===target.id||target.kind==='claim'&&w.claimId===target.id||target.kind==='part'&&w.partId===target.id;if(state.guided&&visible)for(const l of p.guided)add(l.facts);}
 const task=taskOf(w.source,get(w.tasks,p.id));if(task)add(task.facts);const active=activeHelp(w);for(const key of w.help)if(active.has(key)&&own(w.source.help,key))add(w.source.help[key].facts);
 if(p.role==='records'&&validLedgerLearn(state,p)&&!state.folded&&own(w.source,'model')&&validLedgerModel(w.source.model)){const m=w.source.model,stage=find(m.stages,w.modelStage);if(stage){for(const n of stage.counts)if(int(n,1,12)&&int(m.unitValue,1,12))add([[n,m.unitValue]]);if(stage.counts.every(n=>n===stage.counts[0])&&int(stage.counts[0],1,12)&&int(stage.counts.length,1,12))add([[stage.counts.length,stage.counts[0]]]);}}
 if(task){const latest=w.checks.filter(c=>obj(c)&&own(c,'taskId')&&c.taskId===task.id).at(-1);for(const c of [get(w.firstChecks,task.id),latest])if(validLedgerCheck(c))add(c.source.task.facts);}
 if(p.role==='note')for(const kept of [get(w,'firstKept'),get(w,'kept')])if(validLedgerKeep(kept))for(const response of kept.responses)for(const c of [response?.first,response?.latest])if(required(c,['context'])&&required(c.context,['prompt','context','facts'])&&str(c.context.prompt)&&str(c.context.context))add(c.context.facts);
 return [...found.values()];}catch{return [];}}
export function prepareLedgerDisplay(s,o={}){try{if(!ledgerView(s).work)return {ok:true,changed:false};const c=clone(s);o.exposeFacts?.(ledgerFacts(c),c);const changed=JSON.stringify(c)!==JSON.stringify(s);if(!changed)return {ok:true,changed:false};if(!fits(c,o))return {ok:false,changed:false};commit(s,c);return {ok:true,changed:true};}catch{return {ok:false,changed:false};}}
